SELECT x.pid, x.symbol, x.status, x.close_reason, ROUND(x.realized_pnl,6) AS realized_pnl, x.bear15 FROM (SELECT p2.id AS pid, p2.symbol, p2.status, p2.close_reason, p2.realized_pnl, (SELECT COUNT(*) FROM crypto_ai.trade_signal s WHERE s.symbol=es.symbol AND s.interval_code='1m' AND s.decision IN ('SELL','STRONG_SELL') AND s.generated_at < es.generated_at AND s.generated_at >= FROM_UNIXTIME(UNIX_TIMESTAMP(es.generated_at)-900)) AS bear15 FROM crypto_ai.paper_position p2 JOIN crypto_ai.trade_signal es ON es.id=p2.signal_id WHERE p2.status IN ('CLOSED','STOPPED') AND p2.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400)) x WHERE x.bear15 >= 5 OR x.pid IN (137,143,182) ORDER BY x.bear15 DESC, x.pid LIMIT 60;